// Native net-graph export of tutorial_reference_complete.circ
// Not generated by Logisim GUI; source is preserved unchanged.
`default_nettype none
module xor_from_circ(input wire X, input wire Y, output wire Z);
wire n0,n1,n2,n3,n4,n5,n6;
assign n0=X;
assign n1=Y;
assign Z=n6;
not gate_3(n2,n0); // NOT Gate at (250, 100)
not gate_4(n3,n1); // NOT Gate at (250, 300)
and gate_5(n4,n0,n3); // AND Gate at (400, 140)
and gate_6(n5,n2,n1); // AND Gate at (400, 260)
or gate_7(n6,n4,n5); // OR Gate at (550, 200)
endmodule
`default_nettype wire
